//
//  RAGEvalDatasetSchemaTests.swift
//  OpenIntelligenceTests
//
//  Pins the on-disk contract for `Benchmarks/rag_eval_v1.jsonl`.
//
//  That dataset is generated by `scripts/build_eval_dataset.py` from the
//  tiny_research_suite manifest, and it is the only corpus the documented
//  `RAGEvalRunner` / `RAGEvalMetrics` gates have to run against. The file lives
//  outside the test bundle, so these tests decode representative lines inline
//  rather than reading it — the goal is to catch a `RAGEvalCase` schema change
//  that would silently invalidate every row, not to re-validate the file.
//
//  If a test here fails, regenerate the dataset and update these fixtures:
//      python3 scripts/build_eval_dataset.py
//

import XCTest
@testable import OpenIntelligence

final class RAGEvalDatasetSchemaTests: XCTestCase {

    private let decoder = JSONDecoder()

    private func decode(_ line: String) throws -> RAGEvalCase {
        let data = try XCTUnwrap(line.data(using: .utf8))
        return try decoder.decode(RAGEvalCase.self, from: data)
    }

    // MARK: - Representative Rows

    /// Exact-value lookup: the highest-precision category in the suite.
    func testExactValueRowDecodes() throws {
        let line = #"{"id":"exact_fuel_capacity","query":"How many gallons of gasoline can the vehicle hold?","expectedAnswer":"14.3 US gal","category":"exact_value","groundTruthChunkIds":null,"expectedCitations":["vehicle_specs.md"],"shouldAbstain":false,"containerId":null,"qualityMode":"standard","tags":["exact_value","synthetic_financebench_style"],"notes":"fixtures: vehicle_specs.md"}"#

        let evalCase = try decode(line)

        XCTAssertEqual(evalCase.id, "exact_fuel_capacity")
        XCTAssertEqual(evalCase.category, .exactValue)
        XCTAssertEqual(evalCase.expectedAnswer, "14.3 US gal")
        XCTAssertEqual(evalCase.expectedCitations, ["vehicle_specs.md"])
        XCTAssertFalse(evalCase.shouldAbstain)
    }

    /// Multi-hop synthesis across two documents.
    func testMultiDocumentRowDecodes() throws {
        let line = #"{"id":"multi_hop_project_m1","query":"Who owns Project M1 and what is its reporting deadline?","expectedAnswer":"Owner-1A / Q1 review gate","category":"multi_document","groundTruthChunkIds":null,"expectedCitations":["case_1_part_a.md"],"shouldAbstain":false,"containerId":null,"qualityMode":"deepThink","tags":["multi_hop","synthetic_multihop_rag_style"],"notes":"fixtures: case_1_part_a.md, case_1_part_b.md"}"#

        let evalCase = try decode(line)

        XCTAssertEqual(evalCase.category, .multiDocument)
        XCTAssertEqual(evalCase.qualityMode, "deepThink")
        XCTAssertTrue(try XCTUnwrap(evalCase.notes).contains("case_1_part_b.md"))
    }

    /// Negative control: the app must abstain rather than invent an answer.
    func testAbstentionRowDecodes() throws {
        let line = #"{"id":"missing_unreleased_battery","query":"What is the warranty coverage for the unreleased 2032 prototype battery pack?","expectedAnswer":"","category":"abstention","groundTruthChunkIds":null,"expectedCitations":null,"shouldAbstain":true,"containerId":null,"qualityMode":"standard","tags":["missing_evidence","synthetic_negative_control"],"notes":"fixtures: missing_battery_policy.md"}"#

        let evalCase = try decode(line)

        XCTAssertEqual(evalCase.category, .abstention)
        XCTAssertTrue(evalCase.shouldAbstain, "negative controls must be marked abstaining")
        XCTAssertNil(evalCase.expectedCitations, "an abstaining case cites nothing")
    }

    // MARK: - Loader Contract

    /// The generated file carries `//` header comments; the loader must skip them.
    func testCommentAndBlankLinesAreSkipped() throws {
        let jsonl = """
        // OpenIntelligence RAG evaluation dataset v1
        // GENERATED by scripts/build_eval_dataset.py — do not edit by hand.

        {"id":"a","query":"q","expectedAnswer":"x","category":"factual","groundTruthChunkIds":null,"expectedCitations":null,"shouldAbstain":false,"containerId":null,"qualityMode":"standard","tags":null,"notes":null}
        """

        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent("schema-\(UUID().uuidString).jsonl")
        try jsonl.write(to: url, atomically: true, encoding: .utf8)
        defer { try? FileManager.default.removeItem(at: url) }

        let dataset = try RAGEvalDataset.load(from: url)

        XCTAssertEqual(dataset.cases.count, 1, "comments and blank lines must not become cases")
        XCTAssertEqual(dataset.cases.first?.id, "a")
    }

    /// Every category the generator can emit must exist on `EvalCategory`.
    /// `build_eval_dataset.py` maps manifest categories onto these four.
    func testGeneratorTargetCategoriesExist() {
        for raw in ["exact_value", "factual", "multi_document", "abstention"] {
            XCTAssertNotNil(
                EvalCategory(rawValue: raw),
                "build_eval_dataset.py emits '\(raw)', which EvalCategory must accept"
            )
        }
    }
}
